<script lang="ts">
  import {onDestroy} from 'svelte';import {command} from './api';import {createRequestGate} from './requestGate.js';import type {SettingsSnapshot,SettingValue} from './settings';
  let {deviceId}:{deviceId:string|null}=$props();let snapshot=$state<SettingsSnapshot|null>(null);let draft=$state<Record<string,SettingValue>>({});let busy=$state(false);let confirmed=$state(false);let error=$state('');let success=$state('');let loadedId='';const requests=createRequestGate();
  const changes=$derived(Object.entries(draft).filter(([key,value])=>snapshot?.fields.some(field=>field.key===key&&field.available&&field.value!==value)));const dirty=$derived(changes.length>0);const invalid=$derived(changes.length!==1||changes.some(([key,value])=>!snapshot?.fields.find(field=>field.key===key)?.options?.some(option=>option.value===value)));
  function accept(value:SettingsSnapshot){snapshot=value;draft=Object.fromEntries(value.fields.filter(field=>field.value!==null).map(field=>[field.key,field.value!]));confirmed=true;}
  const message=(e:unknown)=>e&&typeof e==='object'&&'message'in e?String(e.message):String(e);
  async function read(){if(!deviceId||busy)return;const current=requests.begin();busy=true;error='';success='';try{const value=await command<SettingsSnapshot>('read_atk_performance',{deviceId});if(current())accept(value);}catch(e){if(current()){error=message(e);confirmed=false;}}finally{if(current())busy=false;}}
  async function apply(){if(!deviceId||!snapshot||busy||invalid||!confirmed)return;const current=requests.begin();const[key,value]=changes[0];busy=true;error='';success='';try{const result=await command<SettingsSnapshot>('apply_atk_performance',{deviceId,change:{key,value,expectedState:snapshot.stateToken}});if(current()){accept(result);success='参数已写入并读回确认。';}}catch(e){if(current()){error=`${message(e)}。请重新读取设备参数。`;confirmed=false;}}finally{if(current())busy=false;}}
  export function hasUnsavedChanges(){return dirty||busy;}export function isOperationPending(){return busy;}
  $effect(()=>{if(loadedId!==(deviceId||'')){loadedId=deviceId||'';requests.invalidate();snapshot=null;draft={};busy=false;confirmed=false;if(deviceId)void read();}});onDestroy(()=>requests.invalidate());
</script>
<div class="parameter-heading"><h3>参数设置</h3><p>每次预览并应用一项参数，保留设备其他设置。</p></div>
<div class="parameter-fields">{#each snapshot?.fields??[] as field}<div class="parameter-field"><div><label for={`atk-${field.key}`}>{field.label}</label>{#if field.description}<p>{field.description}</p>{/if}{#if !field.available}<p>{field.reason||'当前原值未识别，保持只读'}</p>{/if}</div><select id={`atk-${field.key}`} bind:value={draft[field.key]} disabled={busy||!field.available||!confirmed||(dirty&&changes[0]?.[0]!==field.key)}><option value={undefined} disabled>未知</option>{#each field.options??[] as option}<option value={option.value}>{option.label}</option>{/each}</select></div>{/each}</div>
{#if !snapshot}<div class="settings-empty" role="status"><strong>{busy?'正在读取设备参数…':!deviceId?'连接鼠标后读取参数':'尚未取得设备参数'}</strong><p>设备读回后显示可修改项目和原值。</p></div>{/if}
{#if dirty}<div class="change-preview"><strong>待应用的参数</strong>{#each changes as [key,value]}<p>{snapshot?.fields.find(field=>field.key===key)?.label} → {snapshot?.fields.find(field=>field.key===key)?.options?.find(option=>option.value===value)?.label}</p>{/each}</div>{/if}
{#if error}<p class="message error" role="alert">{error}</p>{/if}{#if success}<p class="settings-success" role="status">{success}</p>{/if}
<div class="settings-actions"><span role="status">{busy?'正在与设备通信…':!confirmed&&dirty?'请先撤回预览再重新读取核对。':dirty?'每次应用一项参数，其他设置保留。':''}</span><button class="secondary" disabled={!deviceId||busy||dirty} onclick={read}>重新读取</button><button class="secondary" disabled={busy||!dirty} onclick={()=>{if(snapshot){const wasConfirmed=confirmed;accept(snapshot);confirmed=wasConfirmed;}}}>撤回预览</button><button class="primary" disabled={!dirty||busy||invalid||!confirmed} onclick={apply}>{busy?'等待设备确认…':'应用到设备'}</button></div>
<style>
 .parameter-heading h3{font-size:16px;font-weight:600;margin:0 0 8px}.parameter-heading p,.parameter-field p{font-size:12px;color:var(--muted);line-height:1.65}.parameter-fields{max-width:720px}.parameter-field{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:24px 0;border-bottom:1px solid var(--quiet-line)}.parameter-field>div{min-width:0}.parameter-field label{font-size:14px;font-weight:500}.parameter-field p{font-size:12px;margin:8px 0 0}.parameter-field select{min-width:144px;max-width:100%;background:var(--control);color:var(--ink);padding:8px 12px;border:1px solid var(--line);border-radius:8px;font:inherit;font-size:12px;min-height:36px}@media(max-width:500px){.parameter-field{flex-direction:column;align-items:stretch;gap:12px;padding:16px 0}.parameter-field select{width:100%;min-width:0}}
</style>
